import json
d=json.load(open('prof4.json'))
hs={h['node_id']:h for h in d['hotspots']}
def anc(h):
    out=[]
    p=h.get('parent_id')
    while p is not None and p in hs:
        out.append(hs[p]['syntax_kind'].split('.')[-1]); p=hs[p].get('parent_id')
    return '/'.join(reversed(out))
print('total', d.get('profile_heartbeats'))
for h in sorted([h for h in d['hotspots'] if h['depth']>=6],key=lambda h:-h['heartbeats'])[:25]:
    print(round(h['heartbeats'],1), h['class'], h['syntax_kind'].split('.')[-1], '<<', anc(h)[:60], '|', h['snippet'].replace('\\n',' ')[:60])
EOF"

